import { Transform } from 'class-transformer';
import {
  IsEnum,
  IsIn,
  IsNumber,
  IsOptional,
  IsString,
  IsUUID,
  Max,
  MaxLength,
  Min,
} from 'class-validator';
import {
  CREDIT,
  OrderPaymentMethod,
  PaymentKind,
} from '../entities/order-payment.entity';
import { PaymentMethod } from '../entities/service-order.entity';

const trimToNull = ({ value }) =>
  typeof value === 'string' ? value.trim() || null : value;

export class CreatePaymentDto {
  /** Generated by the screen; repeating it returns the same payment. */
  @IsOptional()
  @IsUUID()
  id?: string;

  @IsEnum(PaymentKind)
  kind: PaymentKind;

  @IsNumber({ maxDecimalPlaces: 2, allowNaN: false, allowInfinity: false })
  @Min(0.01, { message: 'Escribe un importe mayor que 0' })
  @Max(1_000_000)
  amount: number;

  /** 'credit' pays with, or refunds to, the client's saldo a favor. */
  @IsIn([...Object.values(PaymentMethod), CREDIT])
  method: OrderPaymentMethod;

  @Transform(trimToNull)
  @IsOptional()
  @IsString()
  @MaxLength(300)
  note?: string | null;
}
